//  D. Precision Alignment#include<bits/stdc++.h>using namespace std;struct tri{    long long first,second,third;};long long n, k;bool sol(vector<pair<long long,tri>>&a, long long val){    bool ans=true;    long long kk=k;    for(int i=0; i<n; i++){        if(a[i].first>=val)continue;        else{            if(val-a[i].first>kk){ans=false;break;}            long long f=a[i].second.first, s=a[i].second.second, t=a[i].second.third;            if(f==s && s==t){ans=false;break;}            else if(f>s || s>t){                kk-=val-a[i].first;            }            else if( f==s || s==t){                if(val-a[i].first+2>kk){ans=false;break;}                kk-=val-a[i].first+2;            }            else{                if(s-f<=t-s){                    long long sm=2*(s-f+1);                    if(sm+val-a[i].first>kk){ans=false;break;}                    kk-=sm+val-a[i].first;                }                else{                    long long sm=2*(t-s+1);                    if(sm+val-a[i].first>kk){ans=false;break;}                    kk-=sm+val-a[i].first;                }            }        }    }    return ans;}int main(){    ios_base::sync_with_stdio(false);    cin.tie(NULL);    int tt;    cin>>tt;    while(tt--){        cin>>n>>k;        vector<pair<long long,tri>>a(n);        long long mn=LLONG_MAX;        for(int i=0; i<n; i++){            long long p,q,r;            cin>>p>>q>>r;            a[i].first=p+q+r;            mn=min(a[i].first,mn);            a[i].second.first=p;a[i].second.second=q;a[i].second.third=r;        }        long long l=mn, r=mn+k;//         cout<<l<<" "<<r<<" ";        long long ans=l;        while(l<=r){            long long mid=l+(r-l)/2;            if(sol(a,mid)==true){//                 cout<<mid<<" ";                ans=max(ans,mid);                l=mid+1;            }            else{                r=mid-1;            }        }        cout<<ans<<endl;    }    return 0;}